import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>

__global__ void layernorm_fwd_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    const long long rows,
    const long long N,
    const float eps) {
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;
  const bool use_vec = (N & 3LL) == 0LL;
  const long long nvec = use_vec ? (N >> 2) : 0LL;
  const long long tail_begin = use_vec ? (nvec << 2) : 0LL;
  __shared__ double ssum[1024];
  __shared__ double ssq[1024];
  __shared__ float smean;
  __shared__ float srstd;
  // Grid-stride loop over rows: a fixed, device-sized grid covers any
  // number of rows while keeping every launched block doing useful work.
  for (long long row = blockIdx.x; row < rows; row += gridDim.x) {
    const float* xrow = x + row * N;
    float* yrow = y + row * N;
    double sum = 0.0;
    double sumsq = 0.0;
    if (use_vec) {
      const float4* x4 = reinterpret_cast<const float4*>(xrow);
      for (long long i = tid; i < nvec; i += nthreads) {
        const float4 v = x4[i];
        sum += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
        sumsq += (double)v.x * (double)v.x + (double)v.y * (double)v.y +
                 (double)v.z * (double)v.z + (double)v.w * (double)v.w;
      }
    }
    for (long long i = tail_begin + tid; i < N; i += nthreads) {
      const float v = xrow[i];
      sum += (double)v;
      sumsq += (double)v * (double)v;
    }
    ssum[tid] = sum;
    ssq[tid] = sumsq;
    __syncthreads();
    for (int s = nthreads >> 1; s > 0; s >>= 1) {
      if (tid < s) {
        ssum[tid] += ssum[tid + s];
        ssq[tid] += ssq[tid + s];
      }
      __syncthreads();
    }
    if (tid == 0) {
      const double mean = ssum[0] / (double)N;
      double var = ssq[0] / (double)N - mean * mean;
      if (var < 0.0) var = 0.0;
      smean = (float)mean;
      srstd = rsqrtf((float)var + eps);
    }
    __syncthreads();
    const float mean = smean;
    const float rstd = srstd;
    if (use_vec) {
      const float4* x4 = reinterpret_cast<const float4*>(xrow);
      const float4* w4 = reinterpret_cast<const float4*>(w);
      const float4* b4 = reinterpret_cast<const float4*>(b);
      float4* y4 = reinterpret_cast<float4*>(yrow);
      for (long long i = tid; i < nvec; i += nthreads) {
        const float4 xv = x4[i];
        const float4 wv = w4[i];
        const float4 bv = b4[i];
        float4 out;
        out.x = (xv.x - mean) * rstd * wv.x + bv.x;
        out.y = (xv.y - mean) * rstd * wv.y + bv.y;
        out.z = (xv.z - mean) * rstd * wv.z + bv.z;
        out.w = (xv.w - mean) * rstd * wv.w + bv.w;
        y4[i] = out;
      }
    }
    for (long long i = tail_begin + tid; i < N; i += nthreads) {
      yrow[i] = (xrow[i] - mean) * rstd * w[i] + b[i];
    }
    // Ensure all threads are done reading smean/srstd before the next
    // grid-stride iteration overwrites the shared reduction buffers.
    __syncthreads();
  }
}

torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat,
              "weight/bias must be float32");

  auto xc = x.contiguous();
  auto wc = weight.contiguous();
  auto bc = bias.contiguous();

  const long long N = (long long)wc.numel();
  TORCH_CHECK(N > 0, "normalized_shape numel must be positive");
  TORCH_CHECK(xc.numel() % N == 0, "input trailing dims must match normalized_shape");
  const long long rows = (long long)xc.numel() / N;

  auto y = at::empty_like(xc);
  if (rows == 0) return y;

  dim3 block(1024);
  const int num_sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  const long long max_blocks = (long long)num_sms * 2LL;
  const long long grid_blocks = (rows < max_blocks) ? rows : max_blocks;
  dim3 grid((unsigned int)grid_blocks);
  layernorm_fwd_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
      xc.data_ptr<float>(),
      wc.data_ptr<float>(),
      bc.data_ptr<float>(),
      y.data_ptr<float>(),
      rows,
      N,
      (float)eps);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""

_cpp_src = "torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);"

_layernorm_ext = load_inline(
    name="custom_layernorm_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["layernorm_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _layernorm_ext.layernorm_cuda(x, self.weight, self.bias, self.eps)

